package com.exempal.shiftcounter.architecture;
import org.junit.jupiter.api.Test; import java.nio.file.*; import static org.assertj.core.api.Assertions.assertThat;
class UserMigrationContractTest {@Test void migrationDefinesUserSecurityConstraints() throws Exception {var path=Path.of("src/main/resources/db/migration");String sql=Files.readString(path.resolve("V10__introduce_local_users.sql"));String v11=Files.readString(path.resolve("V11__add_user_optimistic_version.sql"));assertThat(sql).contains("CREATE TABLE app_user","pin_hash VARCHAR(255) NOT NULL","USER', 'ADMIN', 'OWNER","ACTIVE', 'BLOCKED","failed_attempts");assertThat(sql.toLowerCase()).doesNotContain("pin varchar","pin char");assertThat(v11).contains("ALTER TABLE app_user ADD COLUMN version BIGINT NOT NULL DEFAULT 0");}}
